export default function input({ response }) {
  const f = response?.definition?.fields,
    a = response?.answers;
  if (!response?.token || !Array.isArray(f) || !Array.isArray(a))
    throw Error("Missing complete Typeform response");
  function read(title, type) {
    const field = f.filter((x) => x.title === title);
    if (field.length !== 1) throw Error("Expected one question " + title);
    const answer = a.filter((x) => x.field?.id === field[0].id);
    if (answer.length !== 1 || answer[0].type !== type) throw Error("Invalid answer " + title);
    return type === "choices" ? answer[0].choices?.labels : answer[0][type];
  }
  const name = read("Great, can we get your full name?", "text"),
    email = read("And what's your email address?", "email"),
    sessions = read("Which sessions would you like to attend?", "choices");
  if (
    !name ||
    !email ||
    !Array.isArray(sessions) ||
    !sessions.length ||
    sessions.some((x) => typeof x !== "string" || !x) ||
    new Set(sessions).size !== sessions.length
  )
    throw Error("Invalid registration");
  return { id: response.token, name, email, sessions, submittedAt: response.submitted_at || "" };
}

