export default async function next(
  {
    id,
    name,
    email,
    sessions,
    submittedAt,
    rows,
    spreadsheetId,
    calendarId,
    teamId,
    acknowledge,
    resolution,
  },
  ctx,
) {
  if (
    !id ||
    !name ||
    !email ||
    !spreadsheetId ||
    !calendarId ||
    !teamId ||
    [spreadsheetId, calendarId, teamId].some((x) => x.includes("YOUR_"))
  )
    throw Error("Configure registration destinations");
  const key = "registration:" + id;
  let s = await ctx.state.get(key);
  if (!s) {
    if (!Array.isArray(rows) || rows.length < 1) throw Error("Missing Sessions table");
    const h = rows[0],
      col = (n) => h.indexOf(n),
      si = col("Session"),
      ci = col("Mattermost Channel ID"),
      ei = col("Google Calendar Event ID");
    if ([si, ci, ei].some((i) => i < 0)) throw Error("Missing Sessions column");
    const matches = sessions.map((name) => {
      const m = rows.slice(1).filter((r) => r[si] === name);
      if (m.length !== 1 || !m[0][ci] || !m[0][ei])
        throw Error("Session must map to one channel and event: " + name);
      return { name, channelId: String(m[0][ci]), eventId: String(m[0][ei]) };
    });
    s = {
      id,
      name,
      email,
      sessions: matches,
      submittedAt,
      phase: "sheet",
      index: 0,
      pending: null,
    };
    await ctx.state.set(key, s);
  }
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.pending);
    if (resolution === "confirmed") {
      if (s.phase === "calendar") s.index++;
      else s.phase = { sheet: "invite", invite: "calendar", welcome: "done" }[s.phase];
    }
    s.pending = null;
    await ctx.state.set(key, s);
  }
  if (s.phase === "calendar" && s.index >= s.sessions.length) {
    s.phase = "welcome";
    await ctx.state.set(key, s);
  }
  const action = s.phase,
    pending =
      action === "done" ? "" : key + ":" + action + (action === "calendar" ? ":" + s.index : "");
  if (pending) {
    s.pending = pending;
    await ctx.state.set(key, s);
  }
  const session = s.sessions[s.index] || s.sessions[0];
  return {
    key,
    pending,
    action,
    spreadsheetId,
    calendarId,
    teamId,
    eventId: session.eventId,
    email: s.email,
    name: s.name,
    values: [[s.name, s.email, s.sessions.map((x) => x.name).join(", "), s.submittedAt, id, ""]],
    invite: { emails: [s.email], channelIds: [...new Set(s.sessions.map((x) => x.channelId))] },
    subject: "Event registration received",
    message: `Dear ${s.name},\n\nYour registration includes:\n${s.sessions.map((x) => "- " + x.name).join("\n")}\n\nYou will receive a Mattermost invitation. Follow it to join the team and selected channels. Calendar invitations will be sent separately.`,
  };
}

