async function confirm({ key, kind, updatedRows, body, eventId, messageId }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || !s.pending || s.phase !== kind) throw Error("Missing pending action");
  if (kind === "sheet" && updatedRows !== 1) throw Error("Unknown sheet result");
  if (kind === "invite") {
    if (!Array.isArray(body) || !body.length || body.some((x) => x.error || x.Error))
      throw Error("Unknown or failed Mattermost invitation");
    const matching = body.some(
      (x) => String(x.email ?? x.Email ?? "").toLowerCase() === s.email.toLowerCase(),
    );
    if (!matching) throw Error("Missing invitation receipt");
  }
  if (kind === "calendar" && eventId !== s.sessions[s.index].eventId)
    throw Error("Unknown calendar result");
  if (kind === "welcome" && !messageId) throw Error("Unknown email result");
  s.pending = null;
  if (kind === "calendar") s.index++;
  else s.phase = { sheet: "invite", invite: "calendar", welcome: "done" }[kind];
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function f(input, ctx) {
  return confirm({ ...input, kind: "sheet" }, ctx);
}

